class Position {
public:
  void addFill(double qty, double px) {
    double nq = qty_ + qty;
    avgPrice_ = (qty_*avgPrice_ + qty*px)/nq;
    qty_ = nq;
  }
private:
  double qty_;
  double avgPrice_;
};

class Order {
public:
  Order(std::string sym, int qty)
    : symbol_(std::move(sym)),
      qty_(qty), id_(nextId_++) {}
private:
  std::string symbol_;
  int qty_;
  const int id_;
  static int nextId_;
};
